  private readonly OriginalNativeMemory m;private readonly OriginalPcGameManagerResources gameManager;private readonly Bindings bindings;private readonly OriginalConfigurationMemoryStrings strings;private readonly OriginalPhysicalCfgTypeEnvironment types;
  private OriginalPcJurisdictionHelpResources help;private OriginalPcJurisdictionReadResources reads;private readonly OriginalJurisdictionFileResources files;private bool disposed;
  private readonly Func<uint,uint,byte> machineByte;private readonly OriginalJurisdictionOffsetTree erase;private readonly OriginalConfigurationRbTree rb;
  public uint PrimaryOwner{get;private set;}public uint InterfaceOwner{get{return PrimaryOwner+4;}}public OriginalPcJurisdictionReadResources ReadResources{get{return reads;}}public OriginalConfigurationMemoryStrings Strings{get{return strings;}}
  public OriginalPcJurisdictionResources(OriginalNativeMemory memory,OriginalPcBootResourceCatalog catalog,OriginalPcGameManagerResources gameManager,Func<uint> configInstance,Func<uint,OriginalConfigurationRegistry> registry,Func<uint,uint,byte> machineByte,bool atomic)
  {
   if(memory==null||catalog==null||gameManager==null||configInstance==null||registry==null||machineByte==null)throw new ArgumentException("Shared native memory and caller-owned PC service ports required");m=memory;this.gameManager=gameManager;this.machineByte=machineByte;
   bindings=JsonUtility.FromJson<Bindings>(File.ReadAllText(catalog.Binding("owner_bindings_v1.json")));foreach(var span in bindings.tables)Ensure(span.address,span.bytes,true);foreach(var path in bindings.paths){Ensure(path.address,path.bytes,true);Ensure(path.slot,new byte[4],false);m.WriteWord(path.slot,path.address);}Ensure(bindings.readMode.address,bindings.readMode.bytes,true);
   Ensure(bindings.jurisdictionInterfaceSlot,new byte[8],false);Ensure(bindings.machineInterfaceSlot,new byte[8],false);if(m.ReadWord(bindings.jurisdictionPrimarySlot)!=0||m.ReadWord(bindings.jurisdictionInterfaceSlot)!=0)throw new InvalidOperationException("Jurisdiction singleton already owned");
   Ensure(0x80000,new byte[0x20000],false);types=new OriginalPhysicalCfgTypeEnvironment(m,atomic);strings=new OriginalConfigurationMemoryStrings(m,0x9b11f28,0x9b12dbc,bindings.readMode.address,bindings.readMode.address,a=>{throw new InvalidDataException("Original COW length error");},a=>{throw new InvalidDataException("Original COW logic error");});PrimaryOwner=m.Allocate(0x290);files=new OriginalJurisdictionFileResources(m,catalog.Resolve);
   OriginalConfigurationRbTree tree=null;tree=new OriginalConfigurationRbTree(new OriginalConfigurationRbTree.Host{ReadWord=m.ReadWord,WriteWord=m.WriteWord,InvokeMutableDecrement=a=>tree.Decrement(a),InvokeMutableIncrement=a=>tree.Increment(a)});rb=tree;erase=new OriginalJurisdictionOffsetTree(new OriginalJurisdictionOffsetTree.Host{ReadWord=m.ReadWord,WriteWord=m.WriteWord,WriteByte=m.WriteByte,New=m.Allocate,Delete=m.Free,Decrement=rb.Decrement,Rebalance=rb.InsertAndRebalance});
   var ctor=new OriginalJurisdictionConstruction(new OriginalJurisdictionConstruction.Host{ReadWord=m.ReadWord,WriteWord=m.WriteWord,WriteByte=m.WriteByte,Write64=m.WriteWide,InitHelpText=a=>{help=new OriginalPcJurisdictionHelpResources(m,strings,a,0x86000,0x9b11f28,0x9b12dbc,0x96c5b87,bindings.readMode.address,b=>{throw new InvalidDataException("Original help substring error");});help.Load(catalog);},Open=files.Open,Close=a=>{files.Close(a);},InvokeGameMode=(a,b)=>unchecked((int)gameManager.Invoke(a,b)),EraseGameMap=erase.Erase,EraseOffsetSet=erase.Erase,EraseHelpMap=(a,b)=>help.Dispose(),DeleteArray=m.Free,DestroyString=strings.Destroy,IsNativeUnwind=e=>false,Resume=e=>{throw e;}},new OriginalJurisdictionConstruction.Layout{DerivedVtable=bindings.jurisdictionPrimaryVtable,DerivedInterfaceVtable=bindings.jurisdictionInterfaceVtable,BaseVtable=bindings.jurisdictionBasePrimaryVtable,BaseInterfaceVtable=bindings.jurisdictionBaseInterfaceVtable,EmptyStringData=bindings.emptyStringData,NvramPathSlot=PathSlot("/nvram_os/jurisdiction.bin"),ReadModeCString=bindings.readMode.address,GameManagerSlot=bindings.gameManagerSlot,SingletonSlot=bindings.jurisdictionPrimarySlot});
   try{ctor.Construct(PrimaryOwner);m.WriteWord(bindings.jurisdictionInterfaceSlot,InterfaceOwner);reads=new OriginalPcJurisdictionReadResources(m,strings,catalog,PrimaryOwner,types,gameManager,configInstance,registry,help.GetHelpText,machineByte);}catch{Dispose();throw;}
