  private void Ensure(uint address,byte[] bytes,bool immutable){int i=0;while(i<bytes.Length){bool present=true;byte value=0;try{value=m.ReadByte(address+(uint)i);}catch(InvalidOperationException){present=false;}if(present){if(immutable&&value!=bytes[i])throw new InvalidDataException("Conflicting original boot bytes");++i;continue;}int first=i;while(++i<bytes.Length){try{m.ReadByte(address+(uint)i);break;}catch(InvalidOperationException){}}var span=new byte[i-first];Array.Copy(bytes,first,span,0,span.Length);m.Map(address+(uint)first,span);}}
  private uint PathSlot(string path){foreach(var item in bindings.paths)if(System.Text.Encoding.ASCII.GetString(item.bytes).TrimEnd('\0')==path)return item.slot;throw new InvalidDataException("Original boot path absent");}
  private void Alive(){if(disposed)throw new ObjectDisposedException("OriginalPcJurisdictionResources");}
  public uint Read(){Alive();uint binary=gameManager.GetSimulated()!=0||m.ReadByte(PrimaryOwner+0x34)!=0?PathSlot("/agk/cfg/jurisdiction.bin"):PathSlot("/nvram_os/jurisdiction.bin");return reads.Read(m.ReadWord(PathSlot("/agk/cfg/jurisdiction.cfg")),m.ReadWord(binary));}
  public byte Init(Func<uint,int> checkIfSwapped,Func<uint,uint,ulong> machineGet64,Action<uint,uint,ulong> machineSet64,Func<uint,uint,byte> jurisdictionConflict)
  {
   Alive();if(checkIfSwapped==null||machineGet64==null||machineSet64==null||jurisdictionConflict==null)throw new ArgumentException("Actual MachineData signature and default-limit dispatch ports required");
   var gameBytes=new OriginalJurisdictionGameBytes(new OriginalJurisdictionGameBytes.Host{ReadWord=m.ReadWord,WriteWord=m.WriteWord,ReadByte=m.ReadByte,WriteByte=m.WriteByte,InvokeUsingEeprom=(a,b)=>Using(a,b),InsertOffset=reads.MarkUsed,InsertByte=GrowGameVector,ReadByteFault=()=>{throw new OriginalJurisdictionInputFault("ReadByte",0x2f7);}});
   var init=new OriginalJurisdictionStartup(new OriginalJurisdictionStartup.Host{ReadWord=m.ReadWord,WriteWord=m.WriteWord,ReadByte=m.ReadByte,InvokeGameMode=(a,b)=>unchecked((int)gameManager.Invoke(a,b)),InvokeRead=(a,b,c,d)=>{if(b!=PrimaryOwner||a!=m.ReadWord(m.ReadWord(b)+0x14))throw new InvalidOperationException("Captured jurisdiction Read dispatch");return (byte)reads.Read(c,d);},InsertUnique=InsertGameMap,ReadGameBytes=gameBytes.ReadGameBytes,CheckIfSwapped=checkIfSwapped,InvokeByte=(a,b)=>b==PrimaryOwner?jurisdictionConflict(a,b):machineByte(a,b),InvokeGet64=machineGet64,InvokeSet64=machineSet64,FaultInit=(a,b,c,d,e)=>{throw new InvalidDataException("Original jurisdiction Init fault");}},new OriginalJurisdictionStartup.Layout{GameManagerSlot=bindings.gameManagerSlot,MachineDataSlot=bindings.machineInterfaceSlot,ConfigPathSlot=PathSlot("/agk/cfg/jurisdiction.cfg"),NvramPathSlot=PathSlot("/nvram_os/jurisdiction.bin"),SimulatedPathSlot=PathSlot("/agk/cfg/jurisdiction.bin"),FaultFormat=0x96adc2c,FaultFile=0x96ac780,FaultFunction=0x96aee48});return init.Init(PrimaryOwner);
  }
  private byte Using(uint method,uint owner){if(owner!=PrimaryOwner||method!=m.ReadWord(m.ReadWord(owner)+0x30))throw new InvalidOperationException("Captured UsingEeprom dispatch");return m.ReadByte(owner+0x34);}
  private uint InsertGameMap(uint tree,uint hint,int key,int value){uint header=tree+4,node=m.ReadWord(tree+8),parent=header;byte left=1;while(node!=0){parent=node;int found=unchecked((int)m.ReadWord(node+16));if(key==found)return node;left=(byte)(key<found?1:0);node=m.ReadWord(node+(left!=0?8u:12u));}uint created=m.Allocate(24);m.WriteWord(created+16,unchecked((uint)key));m.WriteWord(created+20,unchecked((uint)value));rb.InsertAndRebalance(left,created,parent,header);m.WriteWord(tree+20,m.ReadWord(tree+20)+1);return created;}
  private void GrowGameVector(uint vector,uint end,byte value){uint begin=m.ReadWord(vector),count=end-begin,capacity=m.ReadWord(vector+8)-begin,next=m.Allocate(capacity==0?1:capacity*2);if(count!=0)m.CopyBytes(next,begin,count);m.WriteByte(next+count,value);if(begin!=0)m.Free(begin);m.WriteWord(vector,next);m.WriteWord(vector+4,next+count+1);m.WriteWord(vector+8,next+(capacity==0?1:capacity*2));}
  public void Dispose(){if(disposed)return;if(reads!=null)reads.Dispose();if(help!=null)help.Dispose();files.Dispose();erase.Erase(PrimaryOwner+0x270,m.ReadWord(PrimaryOwner+0x278));uint vector=m.ReadWord(PrimaryOwner+0x240);if(vector!=0)m.Free(vector);foreach(uint offset in new uint[]{0x38,0x3c,0x40,0x44,0x1c0,0x1f0})strings.Destroy(PrimaryOwner+offset);types.Dispose();if(m.ReadWord(bindings.jurisdictionPrimarySlot)==PrimaryOwner)m.WriteWord(bindings.jurisdictionPrimarySlot,0);if(m.ReadWord(bindings.jurisdictionInterfaceSlot)==InterfaceOwner)m.WriteWord(bindings.jurisdictionInterfaceSlot,0);m.Free(PrimaryOwner);disposed=true;}
 }
